// rv64Core3BrOnNonNullBasicSource is byte-identical to
// br_on_non_null.0.wasm generated by WABT 1.0.41 from the pinned Release 3
// core/br_on_non_null.wast at revision
// 9d36019973201a19f9c9ebb0f10828b2fe2374aa.
func rv64Core3BrOnNonNullBasicSource(target byte) []byte {
	types := wasmtest.Vec(
		wasmtest.FuncType(nil, []wasm.ValType{wasm.I32}),
		[]byte{0x60, 1, 0x64, 0, 1, 0x7f}, // ((ref 0)) -> i32
		[]byte{0x60, 1, 0x63, 0, 1, 0x7f}, // ((ref null 0)) -> i32
	)
	return wasmtest.Module(
		wasmtest.Section(1, types),
		wasmtest.Section(3, wasmtest.Vec(
			wasmtest.ULEB(1), wasmtest.ULEB(2), wasmtest.ULEB(2),
			wasmtest.ULEB(0), wasmtest.ULEB(0), wasmtest.ULEB(0),
			wasmtest.ULEB(0), wasmtest.ULEB(0), wasmtest.ULEB(0),
			wasmtest.ULEB(0),
		)),
		wasmtest.Section(7, wasmtest.Vec(
			wasmtest.ExportEntry("nonnullable-f", byte(wasm.ExternFunc), 4),
			wasmtest.ExportEntry("nullable-null", byte(wasm.ExternFunc), 5),
			wasmtest.ExportEntry("nullable-f", byte(wasm.ExternFunc), 6),
			wasmtest.ExportEntry("nullable2-null", byte(wasm.ExternFunc), 7),
			wasmtest.ExportEntry("nullable2-f", byte(wasm.ExternFunc), 8),
			wasmtest.ExportEntry("unreachable", byte(wasm.ExternFunc), 9),
		)),
		wasmtest.Section(9, []byte{1, 1, 0, 1, target}),
		wasmtest.Section(10, wasmtest.Vec(
			wasmtest.Code([]byte{0x02, 0x64, 0, 0x20, 0, 0xd6, 0, 0x41, 0x7f, 0x0f, 0x0b, 0x14, 0, 0x0b}),
			wasmtest.Code([]byte{0x02, 0x64, 0, 0x20, 0, 0xd6, 0, 0x41, 0x7f, 0x0f, 0x0b, 0x14, 0, 0x0b}),
			wasmtest.Code([]byte{0x02, 0x63, 0, 0x20, 0, 0xd6, 0, 0x41, 0x7e, 0x0f, 0x0b, 0xd4, 0x14, 0, 0x0b}),
			wasmtest.Code([]byte{0x41, 7, 0x0b}),
			wasmtest.Code([]byte{0xd2, 3, 0x10, 0, 0x0b}),
			wasmtest.Code([]byte{0xd0, 0, 0x10, 1, 0x0b}),
			wasmtest.Code([]byte{0xd2, 3, 0x10, 1, 0x0b}),
			wasmtest.Code([]byte{0xd0, 0, 0x10, 2, 0x0b}),
			wasmtest.Code([]byte{0xd2, 3, 0x10, 2, 0x0b}),
			wasmtest.Code([]byte{0x02, 0x64, 0, 0x00, 0xd6, 0, 0x41, 0x7f, 0x0f, 0x0b, 0x14, 0, 0x0b}),
		)),
	)
}

// rv64Core3BrOnNonNullArgsSource is byte-identical to the third module in the
// same pinned file. Its multi-value block carries one i32 argument beside the
// refined function reference.
func rv64Core3BrOnNonNullArgsSource() []byte {
	return wasmtest.Module(
		wasmtest.Section(1, wasmtest.Vec(
			wasmtest.FuncType([]wasm.ValType{wasm.I32}, []wasm.ValType{wasm.I32}),
			[]byte{0x60, 2, 0x7f, 0x63, 0, 1, 0x7f},
			[]byte{0x60, 0, 2, 0x7f, 0x64, 0},
		)),
		wasmtest.Section(3, wasmtest.Vec(
			wasmtest.ULEB(0), wasmtest.ULEB(1), wasmtest.ULEB(0), wasmtest.ULEB(0),
		)),
		wasmtest.Section(7, wasmtest.Vec(
			wasmtest.ExportEntry("args-null", byte(wasm.ExternFunc), 2),
			wasmtest.ExportEntry("args-f", byte(wasm.ExternFunc), 3),
		)),
		wasmtest.Section(9, []byte{1, 1, 0, 1, 0}),
		wasmtest.Section(10, wasmtest.Vec(
			wasmtest.Code([]byte{0x20, 0, 0x20, 0, 0x6c, 0x0b}),
			wasmtest.Code([]byte{0x02, 0x02, 0x20, 0, 0x20, 1, 0xd6, 0, 0x0f, 0x0b, 0x14, 0, 0x0b}),
			wasmtest.Code([]byte{0x20, 0, 0xd0, 0, 0x10, 1, 0x0b}),
			wasmtest.Code([]byte{0x20, 0, 0xd2, 0, 0x10, 1, 0x0b}),
		)),
	)
}

func TestRV64Core3BrOnNonNullPinnedModules(t *testing.T) {
	tests := []struct {
		name     string
		source   []byte
		hash     string
		target   int
		features CoreFeatures
		types    int
		funcs    int
		exports  int
		run      func(*testing.T, *Instance)
	}{
		{
			name: "basic", source: rv64Core3BrOnNonNullBasicSource(3), hash: "91026eb144d3644d0309352ce73aabaf82078f6ce50eabebceb864e1d136581e", target: 3,
			features: CoreFeatureBulkMemoryOperations | CoreFeatureReferenceTypes | CoreFeatureTypedFunctionReferences,
			types:    3, funcs: 10, exports: 6,
			run: func(t *testing.T, in *Instance) {
				if got, err := in.Invoke("unreachable"); got != nil || err == nil {
					t.Fatal("pinned unreachable result", got, err)
				} else {
					var trap *coreruntime.TrapError
					if !errors.As(err, &trap) || trap.Code != coreruntime.TrapUnreachable || len(trap.Frames) == 0 {
						t.Fatal("pinned unreachable trap", err)
					}
				}
				for name, want := range map[string]uint64{
					"nonnullable-f": 7, "nullable-null": uint64(^uint32(0)), "nullable-f": 7,
					"nullable2-null": uint64(^uint32(1)), "nullable2-f": 7,
				} {
					if got, err := in.Invoke(name); err != nil || !slices.Equal(got, []uint64{want}) {
						t.Fatal("pinned br_on_non_null result/reuse", name, got, err)
					}
				}
				if got, err := in.Invoke("unreachable"); got != nil || err == nil {
					t.Fatal("pinned trap reuse", got, err)
				}
			},
		},
		{
			name: "args", source: rv64Core3BrOnNonNullArgsSource(), hash: "ddf6ebc9a9d2d409e3d982d3833cde5f795061bb3b7e5c8705b28a35818af301", target: 0,
			features: CoreFeatureBulkMemoryOperations | CoreFeatureMultiValue | CoreFeatureReferenceTypes | CoreFeatureTypedFunctionReferences,
			types:    3, funcs: 4, exports: 2,
			run: func(t *testing.T, in *Instance) {
				const dirtyThree = uint64(0xdeadbeef00000003)
				for name, want := range map[string]uint64{"args-null": 3, "args-f": 9} {
					if got, err := in.Invoke(name, dirtyThree); err != nil || !slices.Equal(got, []uint64{want}) {
						t.Fatal("pinned block argument normalization", name, got, err)
					}
				}
			},
		},
	}
	for _, tc := range tests {
		if got := fmt.Sprintf("%x", sha256.Sum256(tc.source)); got != tc.hash {
			t.Fatalf("%s pinned fixture hash = %s, want %s", tc.name, got, tc.hash)
		}
		for _, artifact := range []bool{false, true} {
			t.Run(fmt.Sprintf("%s-artifact%t", tc.name, artifact), func(t *testing.T) {
				if os.Getenv("WAGO_RV64_TAIL_ARTIFACT_MODE") == "load" && !artifact {
					t.Skip("compiler-free artifact case only")
				}
				c := rv64NativeTailCompile(t, "core3-br-on-non-null-"+tc.name, tc.source, artifact)
				if !c.nativeReferenceFunctionABI || !c.nativeReferenceCallABI || !c.nativeReferenceControlABI || c.requiredFeatures != tc.features || compiledStructuralRequiredFeatures(c) != tc.features || !c.needsFuncRefDescs() || c.NumImports != 0 || len(c.Imports) != 0 || c.tableCount() != 0 || c.memoryCount() != 0 || len(c.Globals) != 0 || c.HasStart || len(c.Types) != tc.types || len(c.Funcs) != tc.funcs || len(c.Exports) != tc.exports || len(c.passiveElems) != 1 || !railshotRequiresNativeOwnerScope(c) {
					t.Fatal("pinned br_on_non_null source/artifact witnesses", c.requiredFeatures)
				}
				rt := NewRuntime(WithRuntimeConfig(rv64NativeTailConfig()))
				in := rv64NativeTokenInstantiate(t, rt, c, NewImports())
				if err := c.Close(); err != nil {
					t.Fatal(err)
				}
				rv64AssertCore3PassiveTarget(t, in, tc.target)
				if descriptor, ok := in.localFuncrefDescriptor(tc.target); !ok || descriptor <= uint64(^uint32(0)) {
					t.Fatal("pinned br_on_non_null full-width descriptor", descriptor, ok)
				}
				tc.run(t, in)
				rv64AssertPublicReferenceArgumentScopesClear(t, in)
				if err := in.Close(); err != nil {
					t.Fatal(err)
				}
				if err := rt.Close(); err != nil {
					t.Fatal(err)
				}
				if in.hasPhysicalResources() || c.codeCache.mem != nil || c.codeCache.refs != 0 {
					t.Fatal("pinned br_on_non_null cleanup")
				}
			})
		}
	}
}

func TestRV64Core3BrOnNonNullPinnedSourceGates(t *testing.T) {
	if os.Getenv("WAGO_RV64_TAIL_ARTIFACT_MODE") == "load" {
		t.Skip("source compiler path only")
	}
	publicReference := rv64ReplaceTableStageSection(t, rv64Core3BrOnNonNullBasicSource(3), 7, wasmtest.Section(7, wasmtest.Vec(
		wasmtest.ExportEntry("nonnullable-f", byte(wasm.ExternFunc), 0),
		wasmtest.ExportEntry("nullable-null", byte(wasm.ExternFunc), 5),
		wasmtest.ExportEntry("nullable-f", byte(wasm.ExternFunc), 6),
		wasmtest.ExportEntry("nullable2-null", byte(wasm.ExternFunc), 7),
		wasmtest.ExportEntry("nullable2-f", byte(wasm.ExternFunc), 8),
		wasmtest.ExportEntry("unreachable", byte(wasm.ExternFunc), 9),
	)))
	tests := map[string][]byte{
		"private-passive-target": rv64Core3BrOnNonNullBasicSource(0),
		"active-element": rv64ReplaceTableStageSection(t, rv64Core3BrOnNonNullBasicSource(3), 9,
			wasmtest.Section(9, []byte{1, 0, 0x41, 0, 0x0b, 1, 3})),
		"typed-expression-passive": rv64ReplaceTableStageSection(t, rv64Core3BrOnNonNullBasicSource(3), 9,
			wasmtest.Section(9, []byte{1, 5, 0x70, 1, 0xd2, 3, 0x0b})),
		"reference-valued-public-signature": publicReference,
	}
	for name, source := range tests {
		t.Run(name, func(t *testing.T) {
			rv64RequireCore3SourceValidation(t, source)
		})
	}
}

func TestRV64Core3BrOnNonNullPinnedArtifactGates(t *testing.T) {
	if os.Getenv("WAGO_RV64_TAIL_ARTIFACT_MODE") == "load" {
		t.Skip("hostile retained artifact admission")
	}
	base := rv64NativeTailCompile(t, "core3-br-on-non-null-gates", rv64Core3BrOnNonNullBasicSource(3), false)
	mutations := map[string]func(*Compiled){
		"missing-function-witness": func(c *Compiled) { c.nativeReferenceFunctionABI = false },
		"missing-control-witness":  func(c *Compiled) { c.nativeReferenceControlABI = false },
		"missing-context-trap":     func(c *Compiled) { c.nativeContextTrapABI = false },
		"missing-table-context":    func(c *Compiled) { c.nativeTableContextABI = false },
		"missing-table-reference":  func(c *Compiled) { c.nativeTableReferenceABI = false },
		"register-abi":             func(c *Compiled) { c.registerABIDisabled = false },
		"missing-descriptors":      func(c *Compiled) { c.NeedsFuncRefDescs = false },
		"private-passive-target":   func(c *Compiled) { c.passiveElems[0].Values[0].FuncIndex = 0 },
		"active-passive-state":     func(c *Compiled) { c.passiveElems[0].Mode = ElemModeActive },
		"wrong-function-type":      func(c *Compiled) { c.Funcs[9].TypeIndex = 1 },
		"extra-feature":            func(c *Compiled) { c.requiredFeatures |= CoreFeatureTailCall },
	}
	for name, mutate := range mutations {
		t.Run(name, func(t *testing.T) {
			bad := rv64ReferenceStartCopy(base.executionView())
			mutate(bad)
			if err := railshotValidateCompiled(bad); !errors.Is(err, railshot.ErrUnsupported) {
				t.Fatal("hostile retained br_on_non_null metadata admitted", err)
			}
			blob, err := marshalCompiled(bad)
			if err != nil {
				return
			}
			loaded, err := LoadTrustedArtifact(blob)
			if loaded != nil {
				loaded.Close()
			}
			if err == nil {
				t.Fatal("hostile serialized br_on_non_null metadata admitted")
			}
		})
	}
}

func TestRV64Core3BrOnNonNullCompilerFreeGate(t *testing.T) {
	if os.Getenv("WAGO_RV64_TAIL_ARTIFACT_MODE") != "load" {
		t.Skip("actual compiler-free runtime only")
	}
	if c, err := Compile(nil, rv64Core3BrOnNonNullBasicSource(3)); c != nil || err == nil || !strings.Contains(err.Error(), "source compilation is unavailable") {
		if c != nil {
			c.Close()
		}
		t.Fatal("compiler-free pinned Core 3 br_on_non_null used source compilation", err)
	}
}
